# Utility functions for department management
def get_department_statistics(department_id):
    """Get basic statistics for a department"""
    try:
        department = Department.objects.get(id=department_id)
        courses = Course.objects.filter(department=department)
        students = Student.objects.filter(course__in=courses)
        staff = Staff.objects.filter(department=department)
        
        return {
            'total_courses': courses.count(),
            'total_students': students.count(),
            'total_staff': staff.count(),
            'active_courses': courses.filter(is_active=True).count(),
        }
    except Department.DoesNotExist:
        return {}

def get_department_analytics(department_id):
    """Get analytics data for a department"""
    try:
        department = Department.objects.get(id=department_id)
        courses = Course.objects.filter(department=department)
        students = Student.objects.filter(course__in=courses)
        
        # Calculate average attendance
        attendance_data = Attendance.objects.filter(
            student__in=students
        ).values('student').annotate(
            total_classes=Count('id'),
            present_classes=Count('id', filter=Q(status=True))
        )
        
        avg_attendance = 0
        if attendance_data:
            total_attendance = sum(
                (data['present_classes'] / data['total_classes'] * 100) 
                if data['total_classes'] > 0 else 0 
                for data in attendance_data
            )
            avg_attendance = total_attendance / len(attendance_data)
        
        return {
            'average_attendance': round(avg_attendance, 2),
            'total_courses': courses.count(),
            'total_students': students.count(),
        }
    except Department.DoesNotExist:
        return {}

def get_department_performance_metrics(department_id):
    """Get performance metrics for a department"""
    try:
        department = Department.objects.get(id=department_id)
        courses = Course.objects.filter(department=department)
        students = Student.objects.filter(course__in=courses)
        
        # Calculate pass percentage
        results = Result.objects.filter(student__in=students)
        total_results = results.count()
        passed_results = results.filter(marks__gte=40).count()
        pass_percentage = (passed_results / total_results * 100) if total_results > 0 else 0
        
        return {
            'pass_percentage': round(pass_percentage, 2),
            'total_exams': total_results,
            'passed_exams': passed_results,
        }
    except Department.DoesNotExist:
        return {}

def get_recent_activity(department_id, limit=10):
    """Get recent activity for a department"""
    try:
        department = Department.objects.get(id=department_id)
        courses = Course.objects.filter(department=department)
        students = Student.objects.filter(course__in=courses)
        
        # Get recent attendance records
        recent_attendance = Attendance.objects.filter(
            student__in=students
        ).order_by('-created_at')[:limit]
        
        activities = []
        for attendance in recent_attendance:
            activities.append({
                'type': 'attendance',
                'description': f"{attendance.student.admin.first_name} marked {'present' if attendance.status else 'absent'}",
                'date': attendance.created_at,
            })
        
        return activities
    except Department.DoesNotExist:
        return []

def get_pending_approvals(department_id):
    """Get pending approvals for a department"""
    try:
        department = Department.objects.get(id=department_id)
        courses = Course.objects.filter(department=department)
        students = Student.objects.filter(course__in=courses)
        
        # Get pending leave applications
        pending_leaves = LeaveReport.objects.filter(
            student__in=students,
            status='pending'
        )
        
        approvals = []
        for leave in pending_leaves:
            approvals.append({
                'type': 'leave_application',
                'description': f"Leave application from {leave.student.admin.first_name}",
                'date': leave.created_at,
                'id': leave.id,
            })
        
        return approvals
    except Department.DoesNotExist:
        return []


# Helper function to get staff object for current user
def get_staff_for_user(request):
    """Get Staff object for current user, handling both HOD and Staff user types"""
    if hasattr(request.user, 'staff'):
        return request.user.staff
    else:
        # For HOD/Admin users, return the first staff member or None
        # In production, you might want to create a default staff profile for HOD
        return Staff.objects.first()


def admin_home(request):
    total_staff = Staff.objects.all().count()
    total_students = Student.objects.all().count()
    subjects = Subject.objects.all()
    total_subject = subjects.count()
    total_course = Course.objects.all().count()
    attendance_list = Attendance.objects.filter(subject__in=subjects)
    total_attendance = attendance_list.count()
    attendance_list = []
    subject_list = []
    for subject in subjects:
        attendance_count = Attendance.objects.filter(subject=subject).count()
        subject_list.append(subject.name[:7])
        attendance_list.append(attendance_count)
    context = {
        'page_title': "Administrative Dashboard",
        'total_students': total_students,
        'total_staff': total_staff,
        'total_course': total_course,
        'total_subject': total_subject,
        'subject_list': subject_list,
        'attendance_list': attendance_list

    }
    return render(request, 'hod_template/home_content.html', context)


def add_staff(request):
    form = StaffForm(request.POST or None, request.FILES or None)
    context = {'form': form, 'page_title': 'Add Staff'}
    if request.method == 'POST':
        if form.is_valid():
            first_name = form.cleaned_data.get('first_name')
            last_name = form.cleaned_data.get('last_name')
            address = form.cleaned_data.get('address')
            email = form.cleaned_data.get('email')
            gender = form.cleaned_data.get('gender')
            password = form.cleaned_data.get('password')
            course = form.cleaned_data.get('course')
            
            try:
                user = CustomUser.objects.create_user(
                    email=email, password=password, user_type=2, first_name=first_name, last_name=last_name)
                user.gender = gender
                user.address = address
                user.save()
                
                # Create Staff object
                staff = Staff.objects.create(
                    admin=user,
                    course=course,
                    department=form.cleaned_data.get('department'),
                    designation=form.cleaned_data.get('designation', 'assistant_professor'),
                    employee_id=form.cleaned_data.get('employee_id'),
                    qualification=form.cleaned_data.get('qualification'),
                    specialization=form.cleaned_data.get('specialization'),
                    experience_years=form.cleaned_data.get('experience_years', 0),
                    mobile_number=form.cleaned_data.get('mobile_number'),
                    alternate_mobile=form.cleaned_data.get('alternate_mobile'),
                    emergency_contact=form.cleaned_data.get('emergency_contact'),
                    date_of_birth=form.cleaned_data.get('date_of_birth'),
                    date_of_joining=form.cleaned_data.get('date_of_joining'),
                    status=form.cleaned_data.get('status', 'active'),
                    blood_group=form.cleaned_data.get('blood_group'),
                    aadhaar_number=form.cleaned_data.get('aadhaar_number'),
                    pan_number=form.cleaned_data.get('pan_number'),
                    bank_account_number=form.cleaned_data.get('bank_account_number'),
                    bank_ifsc_code=form.cleaned_data.get('bank_ifsc_code'),
                    bank_name=form.cleaned_data.get('bank_name'),
                    resume=form.cleaned_data.get('resume'),
                    remarks=form.cleaned_data.get('remarks')
                )
                
                messages.success(request, "Successfully Added")
                return redirect(reverse('add_staff'))

            except Exception as e:
                messages.error(request, "Could Not Add " + str(e))
        else:
            messages.error(request, "Please fulfil all requirements")

    return render(request, 'forms/staff_form.html', context)


def add_student(request):
    """
    Simplified student addition with Supabase storage integration
    """
    from .supabase_storage import get_storage
    import secrets
    import string
    import logging
    
    logger = logging.getLogger(__name__)
    logger.info("=" * 80)
    logger.info("ADD STUDENT VIEW CALLED")
    logger.info(f"Request Method: {request.method}")
    
    form = StudentForm(request.POST or None, request.FILES or None)
    context = {
        'form': form,
        'page_title': 'Add Student'
    }
    
    if request.method == 'POST':
        logger.info("POST request received")
        logger.info(f"POST Data: {request.POST.keys()}")
        logger.info(f"FILES Data: {request.FILES.keys()}")
        
        if form.is_valid():
            logger.info("✓ Form is VALID")
            try:
                # Extract form data
                first_name = form.cleaned_data.get('first_name')
                last_name = form.cleaned_data.get('last_name')
                email = form.cleaned_data.get('email').lower()
                gender = form.cleaned_data.get('gender')
                date_of_birth = form.cleaned_data.get('date_of_birth')
                mobile_number = form.cleaned_data.get('mobile_number')
                
                logger.info(f"Basic Info - Name: {first_name} {last_name}, Email: {email}")
                
                # Academic details
                course = form.cleaned_data.get('course')
                session = form.cleaned_data.get('session')
                roll_number = form.cleaned_data.get('roll_number')
                
                logger.info(f"Academic Info - Course: {course}, Session: {session}, Roll: {roll_number}")
                
                # Generate random password
                password_chars = string.ascii_letters + string.digits
                password = ''.join(secrets.choice(password_chars) for _ in range(10))
                
                logger.info(f"Generated password (length: {len(password)})")
                
                # Create user with email as username (no separate username field)
                logger.info("Creating CustomUser object...")
                user = CustomUser.objects.create_user(
                    username=email,  # Use email as username internally
                    email=email,
                    password=password,
                    user_type='3',  # Student type
                    first_name=first_name,
                    last_name=last_name,
                    gender=gender
                )
                logger.info(f"✓ User created successfully with ID: {user.id}")
                
                # Create student instance
                logger.info("Creating Student object...")
                student = form.save(commit=False)
                student.admin = user
                student.date_of_birth = date_of_birth
                student.mobile_number = mobile_number
                student.save()
                logger.info(f"✓ Student created successfully with ID: {student.id}")
                
                # Handle document uploads to Supabase
                logger.info("Starting document upload process...")
                document_fields = ['photo', 'signature', 'aadhaar_card', 'income_certificate', 
                                 'transfer_certificate', 'tenth_certificate']
                
                # Check if any files were uploaded
                has_files = any(request.FILES.get(field) for field in document_fields)
                
                if has_files:
                    logger.info(f"Files detected: {[f for f in document_fields if request.FILES.get(f)]}")
                    try:
                        storage = get_storage()
                        logger.info("✓ Supabase storage initialized")
                        
                        uploaded_count = 0
                        for field_name in document_fields:
                            file = request.FILES.get(field_name)
                            if file:
                                logger.info(f"Uploading {field_name}: {file.name} ({file.size} bytes)")
                                success, file_path, error = storage.upload_file(
                                    file=file,
                                    folder=field_name.replace('_', '-'),
                                    student_id=student.id
                                )
                                
                                if success:
                                    setattr(student, field_name, file_path)
                                    uploaded_count += 1
                                    logger.info(f"✓ {field_name} uploaded successfully: {file_path}")
                                else:
                                    logger.warning(f"✗ Failed to upload {field_name}: {error}")
                        
                        logger.info(f"✓ Uploaded {uploaded_count} documents successfully")
                    
                    except Exception as upload_error:
                        logger.error(f"✗ Document upload error: {upload_error}", exc_info=True)
                        messages.warning(request, f"Document upload skipped: Supabase not configured. Basic info still saved.")
                else:
                    logger.info("No files uploaded, skipping document upload process")
                
                student.save()
                
                # Send credentials email
                logger.info("Attempting to send credentials email...")
                try:
                    from django.core.mail import send_mail
                    from django.conf import settings
                    
                    subject = 'Welcome to EduVision College - Your Login Credentials'
                    message = f"""
Dear {first_name} {last_name},

Welcome to EduVision College! Your student account has been created successfully.

Login Credentials:
------------------
Roll Number: {roll_number}
Email: {email}
Password: {password}

You can login using either your roll number or email address.

Login URL: {request.build_absolute_uri('/login')}

Please change your password after first login for security.

Best regards,
EduVision College Administration
"""
                    
                    send_mail(
                        subject,
                        message,
                        settings.DEFAULT_FROM_EMAIL,
                        [email],
                        fail_silently=True
                    )
                    logger.info(f"✓ Email sent successfully to {email}")
                except Exception as email_error:
                    logger.error(f"✗ Email sending error: {email_error}", exc_info=True)
                
                logger.info("✓✓✓ Student addition completed successfully!")
                messages.success(
                    request, 
                    f"Successfully added student! Login credentials sent to {email}. "
                    f"Temporary password: {password}"
                )
                logger.info(f"Redirecting to manage_student...")
                return redirect(reverse('manage_student'))
                
            except Exception as e:
                logger.error(f"✗✗✗ EXCEPTION in add_student: {str(e)}", exc_info=True)
                messages.error(request, f"Could not add student: {str(e)}")
        else:
            logger.warning("✗ Form is INVALID")
            logger.warning(f"Form errors: {form.errors.as_json()}")
            for field, errors in form.errors.items():
                logger.warning(f"  - {field}: {errors}")
            messages.error(request, "Please correct the errors in the form")
    
    logger.info(f"Rendering template: student_form_simple.html")
    logger.info("=" * 80)
    return render(request, 'forms/student_form_simple.html', context)


